package com.example.provider.controller;

import org.springframework.web.bind.annotation.*;
import java.util.HashMap;
import java.util.Map;

/**
 * 服务提供者 - REST 接口
 *
 * 提供简单的 HTTP 接口，供消费者通过 Feign 远程调用。
 * 这是微服务架构中最基础的"被调用方"。
 */
@RestController
@RequestMapping("/api/provider")
public class ProviderController {

    /**
     * 健康检查接口
     * GET /api/provider/health
     */
    @GetMapping("/health")
    public Map<String, Object> health() {
        Map<String, Object> result = new HashMap<>();
        result.put("status", "UP");
        result.put("service", "provider-service");
        result.put("timestamp", System.currentTimeMillis());
        return result;
    }

    /**
     * 获取用户信息接口（模拟数据库查询）
     * GET /api/provider/user/{id}
     *
     * @param id 用户ID
     * @return 用户信息 Map
     */
    @GetMapping("/user/{id}")
    public Map<String, Object> getUser(@PathVariable Long id) {
        // 模拟从数据库查询用户
        Map<String, Object> user = new HashMap<>();
        user.put("id", id);
        user.put("name", "张三");
        user.put("age", 28);
        user.put("email", "zhangsan@example.com");
        user.put("source", "provider-service");  // 标记数据来源
        return user;
    }

    /**
     * 计算接口（演示带参数的 POST 请求）
     * POST /api/provider/calculate
     *
     * @param params 包含 a, b 的请求体
     * @return 计算结果
     */
    @PostMapping("/calculate")
    public Map<String, Object> calculate(@RequestBody Map<String, Integer> params) {
        int a = params.getOrDefault("a", 0);
        int b = params.getOrDefault("b", 0);

        Map<String, Object> result = new HashMap<>();
        result.put("a", a);
        result.put("b", b);
        result.put("sum", a + b);
        result.put("source", "provider-service");
        return result;
    }

    /**
     * 回显接口（演示带查询参数的请求）
     * GET /api/provider/echo?message=hello
     */
    @GetMapping("/echo")
    public Map<String, String> echo(@RequestParam String message) {
        Map<String, String> result = new HashMap<>();
        result.put("message", message);
        result.put("from", "provider-service");
        return result;
    }
}
