package com.example.consumer.feign;

import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

/**
 * Feign 声明式客户端接口
 *
 * 核心注解 @FeignClient：
 *   - name="provider-service"：指定要调用的目标服务名（对应 Nacos 中注册的服务名）
 *   - path="/api/provider"：统一路径前缀
 *
 * 工作原理：
 *   1. Spring 启动时扫描此接口，生成动态代理实现类
 *   2. 调用方法时，代理类通过服务发现从 Nacos 获取 provider-service 的实例列表
 *   3. 通过 LoadBalancer 选择一个实例（默认轮询），发起 HTTP 请求
 *   4. 自动将返回的 JSON 反序列化为 Java 对象
 *
 * 注意：方法签名必须与 ProviderController 的接口完全一致（路径、参数、返回类型）
 */
@FeignClient(name = "provider-service", path = "/api/provider")
public interface ProviderFeignClient {

    /**
     * 调用 provider 的健康检查接口
     * 对应 ProviderController.health()
     */
    @GetMapping("/health")
    Map<String, Object> health();

    /**
     * 调用 provider 的获取用户接口
     * 对应 ProviderController.getUser(Long id)
     *
     * @PathVariable 必须指定 value，Feign 需要知道路径参数名
     */
    @GetMapping("/user/{id}")
    Map<String, Object> getUser(@PathVariable("id") Long id);

    /**
     * 调用 provider 的计算接口
     * 对应 ProviderController.calculate(Map params)
     *
     * @RequestBody 将 Map 序列化为 JSON 放入请求体
     */
    @PostMapping("/calculate")
    Map<String, Object> calculate(@RequestBody Map<String, Integer> params);

    /**
     * 调用 provider 的回显接口
     * 对应 ProviderController.echo(String message)
     *
     * @RequestParam 将参数拼接到 URL 查询字符串
     */
    @GetMapping("/echo")
    Map<String, String> echo(@RequestParam("message") String message);
}
