package com.example.consumer.controller;

import com.example.consumer.feign.ProviderFeignClient;
import org.springframework.web.bind.annotation.*;
import java.util.HashMap;
import java.util.Map;

/**
 * 服务消费者 - Web 接口
 *
 * 这是面向前端/客户端的接口层。
 * 它本身不处理业务逻辑，而是通过 FeignClient 调用 provider-service 获取数据。
 *
 * 典型的微服务调用链路：
 *   前端浏览器 → consumer-service(:8080) → provider-service(:8070)
 */
@RestController
@RequestMapping("/api/consumer")
public class ConsumerController {

    /**
     * 注入 Feign 客户端（Spring 自动注入代理实现类）
     */
    private final ProviderFeignClient providerFeignClient;

    public ConsumerController(ProviderFeignClient providerFeignClient) {
        this.providerFeignClient = providerFeignClient;
    }

    /**
     * 测试调用 provider 的健康检查
     * GET /api/consumer/health-check
     *
     * 调用链路：
     *   浏览器 → ConsumerController.healthCheck()
     *         → ProviderFeignClient.health()  (Feign 代理发 HTTP 请求)
     *         → ProviderController.health()   (provider 处理并返回)
     */
    @GetMapping("/health-check")
    public Map<String, Object> healthCheck() {
        Map<String, Object> result = new HashMap<>();
        result.put("consumer", "consumer-service");
        // 通过 Feign 远程调用 provider
        Map<String, Object> providerHealth = providerFeignClient.health();
        result.put("provider", providerHealth);
        return result;
    }

    /**
     * 通过 Feign 获取用户信息
     * GET /api/consumer/user/{id}
     */
    @GetMapping("/user/{id}")
    public Map<String, Object> getUser(@PathVariable Long id) {
        Map<String, Object> result = new HashMap<>();
        result.put("caller", "consumer-service");
        // Feign 远程调用
        Map<String, Object> user = providerFeignClient.getUser(id);
        result.put("user", user);
        return result;
    }

    /**
     * 通过 Feign 调用计算接口
     * GET /api/consumer/calculate?a=10&b=20
     *
     * 注意：provider 的 calculate 是 POST 接口，
     * 这里 consumer 用 GET 接收参数，内部转 POST 调用 provider
     */
    @GetMapping("/calculate")
    public Map<String, Object> calculate(@RequestParam int a, @RequestParam int b) {
        Map<String, Object> result = new HashMap<>();
        result.put("caller", "consumer-service");

        // 构建请求参数，通过 Feign POST 调用
        Map<String, Integer> params = new HashMap<>();
        params.put("a", a);
        params.put("b", b);
        Map<String, Object> calcResult = providerFeignClient.calculate(params);
        result.put("calculation", calcResult);
        return result;
    }

    /**
     * 通过 Feign 调用回显接口
     * GET /api/consumer/echo?message=hello
     */
    @GetMapping("/echo")
    public Map<String, Object> echo(@RequestParam String message) {
        Map<String, Object> result = new HashMap<>();
        result.put("caller", "consumer-service");
        // Feign 远程调用
        Map<String, String> echoResult = providerFeignClient.echo(message);
        result.put("echo", echoResult);
        return result;
    }
}
